<!doctype html><html lang="vi"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Điều khiển · <?=e($code)?></title><style>*{box-sizing:border-box}body{margin:0;font:16px system-ui;background:#f0f4fb;color:#173052}main{max-width:920px;margin:auto;padding:16px}header{display:flex;align-items:center;justify-content:space-between;gap:12px;flex-wrap:wrap}h1{font-size:24px;margin:8px 0}a{color:#4758bd}.card{background:#fff;border:1px solid #dbe4f3;padding:18px;border-radius:18px;margin:12px 0;box-shadow:0 8px 24px #1730520a}h2{font-size:21px;white-space:pre-wrap;overflow-wrap:anywhere}.muted{color:#64748b;font-size:13px;line-height:1.5}.counter{font-weight:800;color:#4a41a9}.controls{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:9px;position:sticky;bottom:8px;z-index:2}button{min-height:48px;padding:10px;border:0;border-radius:12px;font:700 14px system-ui;cursor:pointer;background:#e7edfb;color:#2e4380}button.primary{background:#5345cf;color:#fff}button.gold{background:#ffd65e;color:#513a0b}button.danger{background:#ffe2e5;color:#a82b40}button:disabled{opacity:.4;cursor:default}.answer{padding:14px;background:#effaf4;border:1px solid #afdac4;border-radius:12px;white-space:pre-wrap;overflow-wrap:anywhere}.options{display:grid;gap:7px}.options p{margin:0;background:#f3f6fc;padding:9px;border-radius:9px;white-space:pre-wrap}.people{display:flex;flex-wrap:wrap;gap:6px}.people span{padding:6px 9px;border-radius:20px;background:#f0f3f9;font-size:12px}.people span.done{background:#d9f3e7;color:#126841}[hidden]{display:none!important}@media(max-width:480px){main{padding:10px}.card{padding:13px}.controls{grid-template-columns:repeat(2,minmax(0,1fr))}h1{font-size:20px}}</style></head><body><main><header><div><h1>🎛 Điều khiển lượt chơi</h1><span class="counter">Mã <?=e($code)?></span></div><a href="<?=e(BASE_URL.'chieu.php?code='.rawurlencode($code))?>" target="_blank" rel="noopener">📺 Mở màn chiếu ↗</a></header><p class="muted"><?=e((string)($quizSet['title']??''))?> · <?=($session['pace_mode']??'')==='teacher'?'Theo nhịp GV: học sinh theo câu được chọn.':'Theo thời gian: học sinh tự chuyển; nút chuyển câu chỉ đổi nội dung màn chiếu.'?></p><section class="card"><div id="progress" class="counter"></div><h2 id="prompt">Đang tải…</h2><div id="options" class="options"></div><details><summary>🔒 Đáp án riêng cho giáo viên</summary><p id="teacherAnswer" class="answer"></p><p id="teacherExplanation" class="muted"></p></details><p id="status" role="status" aria-live="polite"></p></section><section class="card controls"><button class="primary" data-action="start">▶ Bắt đầu</button><button data-action="prev">← Câu trước</button><button class="primary" data-action="next">Câu tiếp →</button><button data-action="answer">💡 Hiện đáp án</button><button class="gold" data-action="publish">📊 Công bố kết quả</button><button data-action="resume">↩ Hiện câu hỏi</button><button class="danger" data-action="finish">🏆 Kết thúc & xếp hạng</button></section><p class="muted">Hiện đáp án: câu hỏi, đáp án và giải thích. Công bố: đúng/sai và tốp 3. Kết thúc: chốt lượt và hiện bảng xếp hạng.</p><section class="card"><h3 id="count">Học sinh tham gia</h3><div id="people" class="people"></div></section></main><script>
(()=>{'use strict';const code=<?=json_encode($code,JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT)?>,csrf=<?=json_encode($csrf,JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT)?>,endpoint=location.pathname+'?code='+encodeURIComponent(code),$=id=>document.getElementById(id);let state=null,busy=false,polling=false;
function lock(){document.querySelectorAll('[data-action]').forEach(button=>{const action=button.dataset.action,open=state?.status==='open'&&state.phase!=='finished',welcome=state?.phase==='welcome';button.disabled=busy||!state||!open||(action==='start'?!welcome:action==='finish'?false:welcome)||(action==='prev'&&state.index<=0)||(action==='next'&&state.index>=state.total-1);});}
function correct(q){if(q.type==='multi')return(q.keys||[]).map(k=>k+' · '+(q.choices?.[k]||'')).join('\n');if(q.type==='fill')return(q.fill_answers||[]).join(' / ');if(q.type==='order')return(q.steps||[]).join(' → ');if(q.type==='match')return(q.pairs||[]).map(p=>p.join(' → ')).join('\n');return(q.key||'')+' · '+(q.choices?.[q.key]||'');}
async function refresh(){if(polling)return;polling=true;try{const r=await fetch(endpoint+'&api=state',{cache:'no-store'}),s=await r.json();if(!r.ok||!s.ok)throw Error(s.message||'Không tải được lượt chơi');state=s;const q=s.question||{};$('progress').textContent=s.phase==='welcome'?'🎯 Chờ bắt đầu':s.phase==='finished'?'🏁 Đã kết thúc':'Câu '+(s.index+1)+' / '+s.total;$('prompt').textContent=q.text||'Chưa có câu hỏi';$('options').replaceChildren();for(const [k,v]of Object.entries(q.choices||{})){const p=document.createElement('p');p.textContent=k+' · '+v;$('options').appendChild(p);}$('teacherAnswer').textContent=correct(q);$('teacherExplanation').textContent=q.explanation||'Không có giải thích.';$('count').textContent=s.answered+' / '+s.students+' đã trả lời câu hiện tại';$('people').replaceChildren();for(const person of s.roster||[]){const tag=document.createElement('span');tag.textContent=person.name+(person.answered?' ✓':' · Chưa trả lời');tag.className=person.answered?'done':'';$('people').appendChild(tag);}if(!busy)$('status').textContent=s.phase==='welcome'?'Bấm Bắt đầu khi lớp đã sẵn sàng.':s.phase==='finished'?'Lượt đã đóng; bảng xếp hạng đang hiện trên màn chiếu.':s.show_graph?'Đang công bố kết quả.':s.show_correct?'Đang hiện đáp án và giải thích.':'Đang hiển thị câu hỏi.';}catch(e){$('status').textContent=e.message;}finally{polling=false;lock();}}
async function send(action){if(busy||!state)return;if(action==='finish'&&!confirm('Kết thúc lượt chơi? Học sinh không thể gửi thêm đáp án.'))return;busy=true;lock();try{const values={code,csrf,action};if(action==='prev'||action==='next'){values.action='move';values.index=String(state.index+(action==='next'?1:-1));}const r=await fetch(endpoint,{method:'POST',body:new URLSearchParams(values)}),data=await r.json();if(!r.ok||!data.ok)throw Error(data.message||'Không thực hiện được');busy=false;await refresh();}catch(e){$('status').textContent=e.message;}finally{busy=false;lock();}}
document.querySelectorAll('[data-action]').forEach(button=>button.addEventListener('click',()=>send(button.dataset.action)));refresh();setInterval(()=>{if(!document.hidden&&!busy)refresh();},2000);document.addEventListener('visibilitychange',()=>{if(!document.hidden)refresh();});})();
</script><?php require __DIR__.'/game_credit.php'; ?></body></html>
